// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPacifico = makeLoadFont('Pacifico');
const loadCaveat = makeLoadFont('Caveat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: pacificoFamily } = loadPacifico();
const { fontFamily: caveatFamily } = loadCaveat();



export type BinocularAnimationProps = Record<string, any>;

const BinocularAnimation: React.FC<BinocularAnimationProps> = ({
  backgroundColor = "#f0ab16",
  transparentBackground = false,
  durationInSeconds = 10,
  binocularScale = 1,
  outerText = "The secret",
  subtitleText = "CREATED BY",
  mainText = "Malloy Studio",
  skyColor = "#9ebfba",
  waterColor = "#77a6a9",
  landColor = "#445934",
  innerTextColor = "#da4d52",
  outerTextColor = "#fcf3cc",
  lighthouseColor = "#ffffff",
  lighthouseStripeColor = "#da4d52",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Binocular Mask Calculations
  const radius = height * 0.48 * binocularScale; // Leaves a tiny gap at top/bottom when scale is 1
  const centerX1 = width / 2 - radius * 0.7;
  const centerX2 = width / 2 + radius * 0.7;
  const centerY = height / 2;

  // Animations
  const maskScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 100 },
  });

  const sceneSlideY = interpolate(frame, [15, 50], [height * 0.2, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // Subtle breathing/parallax effect inside the binoculars
  const panX = interpolate(
    Math.sin(frame / 40),
    [-1, 1],
    [-width * 0.015, width * 0.015]
  );
  const panY = interpolate(
    Math.cos(frame / 50),
    [-1, 1],
    [-height * 0.01, height * 0.01]
  );

  // Outer Text Animation
  const outerOpacity = interpolate(frame, [70, 100], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const outerRotate = interpolate(frame, [70, 110], [-45, -35], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.back(1.5)),
  });

  // SVG Paths for Scenery
  const leftLandPath = useMemo(
    () => `
    M -100 ${height + 100}
    L -100 ${height * 0.52}
    L ${width * 0.05} ${height * 0.58}
    L ${width * 0.12} ${height * 0.62}
    L ${width * 0.15} ${height * 0.68}
    L ${width * 0.22} ${height * 0.78}
    L ${width * 0.3} ${height * 0.79}
    L ${width * 0.38} ${height * 0.82}
    L ${width * 0.38} ${height + 100}
    Z
  `,
    [width, height]
  );

  const rightLandPath = useMemo(
    () => `
    M ${width + 100} ${height + 100}
    L ${width + 100} ${height * 0.62}
    L ${width * 0.9} ${height * 0.64}
    L ${width * 0.82} ${height * 0.69}
    L ${width * 0.75} ${height * 0.69}
    L ${width * 0.68} ${height * 0.74}
    L ${width * 0.58} ${height * 0.76}
    L ${width * 0.52} ${height * 0.78}
    L ${width * 0.52} ${height + 100}
    Z
  `,
    [width, height]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* SVG Definitions (Masks) */}
      <svg style={{ position: "absolute", width: 0, height: 0 }}>
        <defs>
          <clipPath id="binocular-mask">
            <circle cx={centerX1} cy={centerY} r={radius * maskScale} />
            <circle cx={centerX2} cy={centerY} r={radius * maskScale} />
          </clipPath>
          <clipPath id="lighthouse-base">
            <path d="M -25 0 L -15 -180 L 15 -180 L 25 0 Z" />
          </clipPath>
        </defs>
      </svg>

      {/* The Masked Binocular View */}
      <AbsoluteFill
        style={{
          clipPath: "url(#binocular-mask)",
          WebkitClipPath: "url(#binocular-mask)",
        }}
      >
        <AbsoluteFill style={{ backgroundColor: skyColor }}>
          {/* Inner Scene Parallax Container */}
          <AbsoluteFill
            style={{ transform: `translate(${panX}px, ${panY}px)` }}
          >
            {/* Scenery Shapes */}
            <svg
              width="100%"
              height="100%"
              style={{ overflow: "visible", transform: `translateY(${sceneSlideY}px)` }}
            >
              {/* Water */}
              <rect
                x="-100"
                y={height * 0.73}
                width={width + 200}
                height={height * 0.5}
                fill={waterColor}
              />

              {/* Water Ripples / Details */}
              <path
                d={`M ${width * 0.4} ${height * 0.77} Q ${width * 0.45} ${height * 0.78} ${width * 0.5} ${height * 0.77}`}
                stroke="#689598"
                strokeWidth="4"
                strokeLinecap="round"
                fill="none"
              />
              <path
                d={`M ${width * 0.6} ${height * 0.81} Q ${width * 0.65} ${height * 0.82} ${width * 0.7} ${height * 0.81}`}
                stroke="#689598"
                strokeWidth="4"
                strokeLinecap="round"
                fill="none"
              />

              {/* Left Land */}
              <path d={leftLandPath} fill={landColor} />

              {/* Right Land */}
              <path d={rightLandPath} fill={landColor} />

              {/* Lighthouse */}
              <g
                transform={`translate(${width * 0.78}, ${height * 0.69}) scale(0.85)`}
              >
                {/* Main Body */}
                <path d="M -25 0 L -15 -180 L 15 -180 L 25 0 Z" fill={lighthouseColor} />

                {/* Stripes */}
                <g clipPath="url(#lighthouse-base)">
                  <rect
                    x="-30"
                    y="-50"
                    width="60"
                    height="35"
                    fill={lighthouseStripeColor}
                  />
                  <rect
                    x="-30"
                    y="-110"
                    width="60"
                    height="35"
                    fill={lighthouseStripeColor}
                  />
                  <rect
                    x="-30"
                    y="-170"
                    width="60"
                    height="35"
                    fill={lighthouseStripeColor}
                  />
                </g>

                {/* Walkway Base */}
                <rect x="-22" y="-185" width="44" height="6" fill="#2d3725" />
                
                {/* Light Chamber */}
                <path d="M -12 -185 L -12 -215 L 12 -215 L 12 -185 Z" fill={lighthouseColor} />
                <rect x="-8" y="-210" width="16" height="20" fill="#fcf3cc" opacity={0.9} />
                
                {/* Roof */}
                <path d="M -16 -215 L 16 -215 L 0 -235 Z" fill={lighthouseStripeColor} />
                
                {/* Small dome ball */}
                <circle cx="0" cy="-235" r="4" fill={lighthouseColor} />
              </g>
            </svg>

            {/* Inner Text Overlay */}
            <AbsoluteFill
              style={{
                justifyContent: "center",
                alignItems: "center",
                transform: "translateY(-4%)", // Shift up slightly to balance visually
              }}
            >
              {/* Subtitle */}
              <div
                style={{
                  display: "flex",
                  gap: "6px",
                  marginBottom: "-10px",
                }}
              >
                {subtitleText.split("").map((char, i) => {
                  const charDelay = 40 + i * 2;
                  const charScale = spring({
                    frame: frame - charDelay,
                    fps,
                    config: { damping: 12 },
                  });
                  const charOpacity = interpolate(
                    frame - charDelay,
                    [0, 10],
                    [0, 1],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                  );

                  return (
                    <span
                      key={`sub-${i}`}
                      style={{
                        fontFamily: interFamily,
                        fontSize: "1.5rem",
                        fontWeight: 600,
                        letterSpacing: "0.15em",
                        color: innerTextColor,
                        textTransform: "uppercase",
                        opacity: charOpacity,
                        transform: `scale(${charScale})`,
                        display: "inline-block",
                      }}
                    >
                      {char === " " ? "\u00A0" : char}
                    </span>
                  );
                })}
              </div>

              {/* Main Text */}
              <div style={{ display: "flex", flexWrap: "nowrap" }}>
                {mainText.split("").map((char, i) => {
                  // Faster sequence for main text, slightly delayed after subtitle
                  const charDelay = 55 + i * 1.5;
                  const charScale = spring({
                    frame: frame - charDelay,
                    fps,
                    config: { damping: 10, stiffness: 120 },
                  });
                  const charOpacity = interpolate(
                    frame - charDelay,
                    [0, 8],
                    [0, 1],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                  );
                  const charRotate = interpolate(
                    frame - charDelay,
                    [0, 20],
                    [random(`rot-${i}`) * 30 - 15, 0],
                    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.back()) }
                  );

                  return (
                    <span
                      key={`main-${i}`}
                      style={{
                        fontFamily: pacificoFamily,
                        fontSize: "7.5rem",
                        color: innerTextColor,
                        opacity: charOpacity,
                        transform: `scale(${charScale}) rotate(${charRotate}deg)`,
                        display: "inline-block",
                        padding: "0 2px", // Prevents clipping of script flourishes
                        lineHeight: 1.2,
                        textShadow: `2px 2px 0px ${skyColor}80`, // Subtle pop against background
                      }}
                    >
                      {char === " " ? "\u00A0" : char}
                    </span>
                  );
                })}
              </div>
            </AbsoluteFill>
          </AbsoluteFill>
        </AbsoluteFill>
      </AbsoluteFill>

      {/* Outer Content (The text outside the binoculars) */}
      <AbsoluteFill>
        <div
          style={{
            position: "absolute",
            left: width * 0.12,
            top: height * 0.45,
            transform: `rotate(${outerRotate}deg)`,
            opacity: outerOpacity,
            fontFamily: caveatFamily,
            fontSize: "4.5rem",
            color: outerTextColor,
            fontWeight: 500,
            transformOrigin: "left center",
          }}
        >
          {outerText}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default BinocularAnimation;